              },
              "additionalProperties": false
            }
          ]
        }
      },
      "additionalProperties": false
    },
    "constitution": {
      "type": "object",
      "required": [
        "stdo",
        "additional_authorities",
        "entrypoints",
        "agent_bootstrap"
