          "type": "array",
          "items": {
            "$ref": "#/$defs/localAxiom"
          },
          "uniqueItems": true
        },
        "overrides": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localOverride"
          },
          "uniqueItems": true
        },
        "disambiguations": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localDisambiguation"
          },
          "uniqueItems": true
        }
      },
      "additionalProperties": false
    },
    "reference_frame_bases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/referenceFrameBasis"
      },
      "uniqueItems": true
    },
    "what": {
      "type": "object",
      "required": [
        "intent",
        "product",
        "specification"
      ],
      "properties": {
        "intent": {
          "$ref": "#/$defs/referenceUri"
        },
        "product": {
          "$ref": "#/$defs/referenceUri"
        },
        "specification": {
          "$ref": "#/$defs/nonEmptyReferences"
        }
      },
      "additionalProperties": false
    },
    "how": {
      "type": "object",
      "required": [
