        "build_tenants": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/buildTenant"
          },
          "uniqueItems": true
        }
      },
      "additionalProperties": false
    },
    "ticketing": {
      "type": "object",
      "required": [
