    "stdoBinding": {
      "type": "object",
      "required": [
        "source",
        "selector",
        "basis"
      ],
      "properties": {
        "source": {
          "type": "object",
          "required": [
            "repository"
          ],
          "properties": {
            "repository": {
              "$ref": "#/$defs/referenceUri",
              "description": "Git repository carrying selected legacy RC lines or explicit stable-v1 immutable releases."
            }
          },
          "additionalProperties": false
        },
        "selector": {
          "$ref": "#/$defs/stdoChannelUri",
          "description": "Version discovery route: legacy annotated highest-RC selector, or the exact annotated stable-v1 cut on its fresh version line. Never operative authority without digest-bound resolution and explicit adoption."
        },
        "basis": {
          "type": "object",
          "required": [
            "uri",
            "manifest_sha256"
          ],
          "properties": {
            "uri": {
              "$ref": "#/$defs/stdoReleaseUri",
              "description": "Exact immutable installed STDO cut selected by this Product Definition."
            },
            "manifest_sha256": {
              "$ref": "#/$defs/sha256",
              "description": "Digest of the deterministic installed-release manifest carrying tag, commit, tree, and complete distribution identity."
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "constitutionalEntrypoint": {
      "type": "object",
      "required": [
        "basis",
        "uri"
      ],
      "properties": {
        "basis": {
          "$ref": "#/$defs/referenceUri",
          "description": "Reference to the constitutional basis against which the entrypoint URI resolves."
        },
        "uri": {
          "$ref": "#/$defs/referenceUri",
          "description": "Reading route relative to the referenced constitutional basis."
        }
      },
      "additionalProperties": false
    },
    "agentBootstrap": {
      "type": "object",
      "required": [
        "entrypoint",
        "targets"
      ],
      "properties": {
        "entrypoint": {
          "$ref": "#/$defs/referenceUri",
          "description": "Reference to the constitutional entrypoint loaded by the stable agent bootstrap."
