    "product": {
      "type": "object",
      "required": [
        "definition_id",
        "name",
        "source_project",
        "bounded_context"
      ],
      "properties": {
        "definition_id": {
          "$ref": "#/$defs/identityUri"
        },
        "name": {
          "type": "string",
          "minLength": 1
        },
        "source_project": {
          "$ref": "#/$defs/referenceUri"
        },
        "bounded_context": {
          "description": "Optional enclosing bounded context for this product WHAT. It is not an exhaustive registry of subordinate, peer, composed, tenant, user, or runtime contexts.",
          "oneOf": [
            {
              "type": "null"
            },
            {
              "type": "object",
              "required": [
                "id",
                "definition"
              ],
              "properties": {
                "id": {
                  "$ref": "#/$defs/identityUri"
                },
                "definition": {
                  "$ref": "#/$defs/referenceUri"
                }
              },
              "additionalProperties": false
            }
          ]
