          },
          "uniqueItems": true
        },
        "overrides": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localOverride"
          },
          "uniqueItems": true
        },
        "disambiguations": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localDisambiguation"
          },
          "uniqueItems": true
