        "specification"
      ],
      "properties": {
        "intent": {
          "$ref": "#/$defs/referenceUri"
        },
        "product": {
          "$ref": "#/$defs/referenceUri"
        },
        "specification": {
          "$ref": "#/$defs/nonEmptyReferences"
        }
      },
      "additionalProperties": false
    },
    "how": {
      "type": "object",
      "required": [
        "common",
        "build_tenants"
      ],
      "properties": {
        "common": {
          "$ref": "#/$defs/references"
        },
        "build_tenants": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/buildTenant"
          },
          "uniqueItems": true
        }
      },
      "additionalProperties": false
    },
    "ticketing": {
      "type": "object",
      "required": [
