    "sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "stdoChannelUri": {
      "allOf": [
        {
          "$ref": "#/$defs/identityUri"
        },
        {
          "pattern": "^stdo://channels/(?![^/]*-rc\\.)[0-9A-Za-z][0-9A-Za-z._+-]*/?$"
        }
      ]
    },
    "stdoReleaseUri": {
      "allOf": [
        {
          "$ref": "#/$defs/identityUri"
