        {
          "pattern": "^stdo://releases/(?:v[0-9A-Za-z][0-9A-Za-z._+-]*-rc\\.[1-9][0-9]*|v(?:0|[1-9][0-9]*)\\.(?:0|[1-9][0-9]*)\\.(?:0|[1-9][0-9]*))/?$"
        }
      ]
    },
    "stdoBinding": {
      "type": "object",
      "required": [
        "source",
        "selector",
        "basis"
      ],
      "properties": {
        "source": {
          "type": "object",
          "required": [
            "repository"
          ],
          "properties": {
            "repository": {
              "$ref": "#/$defs/referenceUri",
              "description": "Git repository carrying selected legacy RC lines or explicit stable-v1 immutable releases."
            }
          },
          "additionalProperties": false
        },
        "selector": {
          "$ref": "#/$defs/stdoChannelUri",
