        },
        "authority": {
          "$ref": "#/$defs/nonEmptyReferences"
        },
        "applies_to": {
          "$ref": "#/$defs/nonEmptyReferences"
        }
      },
      "additionalProperties": false
    },
    "buildTenant": {
      "type": "object",
      "required": [
        "id",
        "root",
        "design",
